/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreasePriceDiscGroup</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_recordId2">
///    The record ID2 of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_recordId3">
///    The record ID2 of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_recordId4">
///    The record ID2 of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreasePriceDiscGroup</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreasePriceDiscGroup find(  AVAPriceIncreaseSet    _recordId,
                                                    PriceGroupId           _recordId2,
                                                    PriceDiscModule        _recordId3,
                                                    PriceGroupType         _recordId4,
                                                    boolean                _forUpdate = false)
{
    AVAPriceIncreasePriceDiscGroup record;

    if (    _recordId 
        &&  _recordId2  )
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint PriceIncreasePriceDiscGroupIdx
        where   record.PriceIncreaseSet == _recordId
            &&  record.GroupId          == _recordId2
            &&  record.Module           == _recordId3
            &&  record.Type             == _recordId4;
    }
    return record;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreaseLine</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreasePriceDiscGroup</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreasePriceDiscGroup</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreasePriceDiscGroup findByRecId(   RecId   _recordId,
                                                            boolean _forUpdate = false)
{
    AVAPriceIncreasePriceDiscGroup record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        where record.RecId == _recordId;
    }
    return record;
}

/// <summary>
///     AVA <c>addFromAVAPriceIncreaseTable</c> method.
/// </summary>
/// <param name="_record">
///     <c>AVAPriceIncreaseTable</c> as type
/// </param>
/// <param name="_checkOnly">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean addFromAVAPriceIncreaseTable(AVAPriceIncreaseTable   _record,
                                            boolean                 _checkOnly  = false)
{
    // 2009: class: NDX_HVNew method: static void fillHVNewPriceDiscGroup(NDX_HVNewPriceSet  nDX_HVNewPriceSet, boolean checkOnly = false)
    boolean retVal;

    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;
    AVAPriceIncreaseTable           locAVAPriceIncreaseTable;
    PriceDiscGroup                  locPriceDiscGroup;
    int                             i, j;

    Set                             locKCS_GoodsIdSetDefined;
    SetEnumerator                   locKCS_GoodsIdSetEnumeratorDefined;
    Set                             locKCS_GoodsIdSetAVAPriceIncreasePriceDiscGroup;
    boolean                         locKCS_GoodsIdMatch;

    retVal                      = true;
    locAVAPriceIncreaseTable    = _record;

    locKCS_GoodsIdSetDefined    = new Set(Types::String);
    locKCS_GoodsIdSetDefined    = locAVAPriceIncreaseTable.getKCS_GoodsIdSetDefined();

    locKCS_GoodsIdSetAVAPriceIncreasePriceDiscGroup = new Set(Types::String);

    if (locKCS_GoodsIdSetDefined.empty())
    {   
        // no KCS_goodsIds defined
        return false;
    }
    else
    {
        locKCS_GoodsIdSetEnumeratorDefined = locKCS_GoodsIdSetDefined.getEnumerator();
    }

    // find new records
    while select locPriceDiscGroup
    where   locPriceDiscGroup.Module        == ModuleInventCustVend::Cust
        &&  locPriceDiscGroup.NDX_Blocked   == NoYes::No
        &&  (   locPriceDiscGroup.Type      == PriceGroupType::PriceGroup // ToDo: PriceGroupType::KCS_PRCActionPriceGroup is missing
            ||  locPriceDiscGroup.Type      == PriceGroupType::PriceGroup   )
        notexists join forUpdate  locAVAPriceIncreasePriceDiscGroup
        where   locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet  == locAVAPriceIncreaseTable.PriceIncreaseSet
            &&  locAVAPriceIncreasePriceDiscGroup.Module            == locPriceDiscGroup.Module
            &&  locAVAPriceIncreasePriceDiscGroup.Type              == locPriceDiscGroup.Type
            &&  locAVAPriceIncreasePriceDiscGroup.GroupId           == locPriceDiscGroup.GroupId
    {
        i++;
        locKCS_GoodsIdMatch = false;
        locKCS_GoodsIdSetAVAPriceIncreasePriceDiscGroup = locPriceDiscGroup.avaGetKCS_GoodsIdSet();
        if (!locKCS_GoodsIdSetAVAPriceIncreasePriceDiscGroup.empty())
        {
            locKCS_GoodsIdSetEnumeratorDefined.reset();
            while (locKCS_GoodsIdSetEnumeratorDefined.moveNext())
            {
                if(locKCS_GoodsIdSetAVAPriceIncreasePriceDiscGroup.in(locKCS_GoodsIdSetEnumeratorDefined.current()))
                {
                    locKCS_GoodsIdMatch = true;
                }
            }
        }

        if (locKCS_GoodsIdMatch && !_checkOnly)
        {
            ttsbegin;
            locAVAPriceIncreasePriceDiscGroup.clear();
            locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet  = locAVAPriceIncreaseTable.PriceIncreaseSet;
            locAVAPriceIncreasePriceDiscGroup.Module            = locPriceDiscGroup.Module;
            locAVAPriceIncreasePriceDiscGroup.Type              = locPriceDiscGroup.Type;
            locAVAPriceIncreasePriceDiscGroup.GroupId           = locPriceDiscGroup.GroupId;
            locAVAPriceIncreasePriceDiscGroup.PriceDiscRegion   = locPriceDiscGroup.AVAPriceDiscRegion;
            if (locAVAPriceIncreasePriceDiscGroup.validateWrite())
            {
                locAVAPriceIncreasePriceDiscGroup.write();
            }
            ttscommit;
        }
    }
    // find records with NDX_Blocked changed in the meantime
    while select locPriceDiscGroup
    where   locPriceDiscGroup.Module    == ModuleInventCustVend::Cust
        &&  (   locPriceDiscGroup.Type  == PriceGroupType::PriceGroup // ToDo: PriceGroupType::KCS_PRCActionPriceGroup is missing
            ||  locPriceDiscGroup.Type  == PriceGroupType::PriceGroup   )
        notexists join forUpdate  locAVAPriceIncreasePriceDiscGroup
        where   locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet  == locAVAPriceIncreaseTable.PriceIncreaseSet
            &&  locAVAPriceIncreasePriceDiscGroup.Module            == locPriceDiscGroup.Module
            &&  locAVAPriceIncreasePriceDiscGroup.Type              == locPriceDiscGroup.Type
            &&  locAVAPriceIncreasePriceDiscGroup.GroupId           == locPriceDiscGroup.GroupId
            &&  locAVAPriceIncreasePriceDiscGroup.Blocked           == locPriceDiscGroup.NDX_Blocked
    {
        j++;
        if (!_checkOnly)
        {
            ttsbegin;
            locAVAPriceIncreasePriceDiscGroup = AVAPriceIncreasePriceDiscGroup::find(   locAVAPriceIncreaseTable.PriceIncreaseSet,
                                                                                        locPriceDiscGroup.GroupId,
                                                                                        locPriceDiscGroup.Module,
                                                                                        locPriceDiscGroup.Type,
                                                                                        true                        );
            if(locAVAPriceIncreasePriceDiscGroup.RecId)
            {
                locAVAPriceIncreasePriceDiscGroup.Blocked   = locPriceDiscGroup.NDX_Blocked;
                locAVAPriceIncreasePriceDiscGroup.update();
            }
            ttscommit;
        }
    }
    return retVal;
}

/// <summary>
///     AVA <c>countPriceGroupMembersFromAVAPriceIncreaseTable</c> method.
/// </summary>
/// <param name="_record">
///     <c>AVAPriceIncreaseTable</c> as type
/// </param>
/// <param name="_checkOnly">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean countPriceGroupMembersFromAVAPriceIncreaseTable( AVAPriceIncreaseTable   _record,
                                                                boolean                 _checkOnly  = false)
{
    // 2009: class: NDX_HVNew method: static void countPriceGroupMembers(NDX_HVNewPriceSet  nDX_HVNewPriceSet)
    boolean retVal;

    AVAPriceIncreasePriceDiscGroup      locAVAPriceIncreasePriceDiscGroup;
    CustTable                           locCustTable;
    PriceDiscTable                      locPriceDiscTable;
    AVANoOfCustomers                    locAVANoOfCustomers;
    AVANoOfPrices                       locAVANoOfPrices;
    int                                 locNoOfChains;

    //NDXMultipleS_smmBusRelChainGroup    locNDXMultipleS_smmBusRelChainGroup;
    smmBusRelChainGroup                 locsmmBusRelChainGroup;

    AVAPriceIncreaseTable               locAVAPriceIncreaseTable;
    //InventTable                         locInventTable;
    PriceDiscGroup                      locPriceDiscGroup;
    date                                locToday;
    date                                locTodayBefore;


    locAVAPriceIncreaseTable    = _record;
    locToday                    = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    locTodayBefore              = locToday - 1;

    while select forUpdate locAVAPriceIncreasePriceDiscGroup
    where   locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet == locAVAPriceIncreaseTable.PriceIncreaseSet
        join    locPriceDiscGroup
        where   locPriceDiscGroup.Module    == locAVAPriceIncreasePriceDiscGroup.module
            &&  locPriceDiscGroup.Type      == locAVAPriceIncreasePriceDiscGroup.type
            &&  locPriceDiscGroup.GroupId   == locAVAPriceIncreasePriceDiscGroup.GroupId
    {
        locAVANoOfCustomers = 0;
        locAVANoOfPrices    = 0;
        locNoOfChains       = 0;

        //locPriceDiscGroup = locAVAPriceIncreasePriceDiscGroup.priceDiscGroup();

        if(     locAVAPriceIncreasePriceDiscGroup.Module    == ModuleInventCustVend::Cust 
            /*  2009:PriceGroupType::KCS_PRCActionPriceGroup does not exist   
            &&  locAVAPriceIncreasePriceDiscGroup.Type      == PriceGroupType::KCS_PRCActionPriceGroup) */
            &&  locAVAPriceIncreasePriceDiscGroup.Type      == PriceGroupType::PriceGroup )
        {
            /*
            // Kunden mit dieser Aktionspreisgruppe
            select count(RecId)
            from    locCustTable
            //where   locCustTable.PriceGroup == locAVAPriceIncreasePriceDiscGroup.GroupId;
            where   locCustTable.AVANetPG2 == locAVAPriceIncreasePriceDiscGroup.GroupId;
            locAVANoOfCustomers = int642int(locCustTable.RecId);
            */

            locAVANoOfCustomers = 0;

            switch (locPriceDiscGroup.AVAPriceGroupType)
            {
                case AVAPriceGroupType::PriceGroup:
                    /*                        
                    while select locCustTable
                    where   locCustTable.PriceGroup     == locAVAPriceIncreasePriceDiscGroup.GroupId
                    {
                        if(locCustTable.PriceGroup == locAVAPriceIncreasePriceDiscGroup.GroupId)
                        {
                            locAVANoOfCustomers++;
                        }
                    }
                    */
                    select count(RecId)
                    from    locCustTable
                    where   locCustTable.PriceGroup == locAVAPriceIncreasePriceDiscGroup.GroupId;
                    locAVANoOfCustomers = int642int(locCustTable.RecId);
                    break;

                case AVAPriceGroupType::NetPG1:
                    /*
                    while select locCustTable
                    where   locCustTable.AVANetPG1      == locAVAPriceIncreasePriceDiscGroup.GroupId
                        ||  locCustTable.CompanyChainId != ''
                    {
                        if(locCustTable.AVANetPG1  == locAVAPriceIncreasePriceDiscGroup.GroupId)
                        {
                            locAVANoOfCustomers++;
                        }
                        else if(locCustTable.CompanyChainId != '')
                        {
                            select firstonly1 locsmmBusRelChainGroup
                            where   locsmmBusRelChainGroup.ChainId      == locCustTable.CompanyChainId
                                &&  locsmmBusRelChainGroup.AVANetPG1    == locAVAPriceIncreasePriceDiscGroup.GroupId;
                            if(locsmmBusRelChainGroup.RecId)
                            {
                                locAVANoOfCustomers++;
                            }
                        }
                    }
                    */
                    select count(RecId)
                    from    locCustTable
                    where   locCustTable.AVANetPG1      == locAVAPriceIncreasePriceDiscGroup.GroupId;
                    locAVANoOfCustomers = int642int(locCustTable.RecId);
                    /*
                    select count(RecId)
                    from    locCustTable
                    where   locCustTable.AVANetPG1      != locAVAPriceIncreasePriceDiscGroup.GroupId
                        &&  locCustTable.CompanyChainId != '';
                    locNoOfChains       = int642int(locCustTable.RecId);
                    */
                    /*
                    while select locCustTable
                    where   locCustTable.AVANetPG1      != locAVAPriceIncreasePriceDiscGroup.GroupId
                        ||  locCustTable.CompanyChainId != ''
                    {
                        select firstonly1 locsmmBusRelChainGroup
                            where   locsmmBusRelChainGroup.ChainId      == locCustTable.CompanyChainId
                                &&  locsmmBusRelChainGroup.AVANetPG1    == locAVAPriceIncreasePriceDiscGroup.GroupId;
                        if(locsmmBusRelChainGroup.RecId)
                        {
                            locNoOfChains++;
                        }
                    }
                    */
                    while select locCustTable
                    where   locCustTable.AVANetPG1      != locAVAPriceIncreasePriceDiscGroup.GroupId
                        ||  locCustTable.CompanyChainId != ''
                        exists join locsmmBusRelChainGroup
                        where   locsmmBusRelChainGroup.ChainId      == locCustTable.CompanyChainId
                            &&  locsmmBusRelChainGroup.AVANetPG1    == locAVAPriceIncreasePriceDiscGroup.GroupId
                    {
                        locNoOfChains++;
                    }
                    break;

                case AVAPriceGroupType::NetPG2:
                    /*
                    while select locCustTable
                    where   locCustTable.AVANetPG2      == locAVAPriceIncreasePriceDiscGroup.GroupId
                        ||  locCustTable.CompanyChainId != ''
                    {
                        if(locCustTable.AVANetPG2  == locAVAPriceIncreasePriceDiscGroup.GroupId)
                        {
                            locAVANoOfCustomers++;
                        }
                        else if(locCustTable.CompanyChainId != '')
                        {
                            select firstonly1 locsmmBusRelChainGroup
                            where   locsmmBusRelChainGroup.ChainId      == locCustTable.CompanyChainId
                                &&  locsmmBusRelChainGroup.AVANetPG2    == locAVAPriceIncreasePriceDiscGroup.GroupId;
                            if(locsmmBusRelChainGroup.RecId)
                            {
                                locAVANoOfCustomers++;
                            }
                        }
                    }
                    */
                    select count(RecId)
                    from    locCustTable
                    where   locCustTable.AVANetPG2      == locAVAPriceIncreasePriceDiscGroup.GroupId;
                    locAVANoOfCustomers = int642int(locCustTable.RecId);
                    /*
                    while select locCustTable
                    where   locCustTable.AVANetPG2      != locAVAPriceIncreasePriceDiscGroup.GroupId
                        &&  locCustTable.CompanyChainId != ''

                    {
                            select firstonly1 locsmmBusRelChainGroup
                            where   locsmmBusRelChainGroup.ChainId      == locCustTable.CompanyChainId
                                &&  locsmmBusRelChainGroup.AVANetPG2    == locAVAPriceIncreasePriceDiscGroup.GroupId;
                            if(locsmmBusRelChainGroup.RecId)
                            {
                                locNoOfChains++;
                            }

                    }
                    */
                    while select locCustTable
                    where   locCustTable.AVANetPG2      != locAVAPriceIncreasePriceDiscGroup.GroupId
                        ||  locCustTable.CompanyChainId != ''
                        exists join locsmmBusRelChainGroup
                        where   locsmmBusRelChainGroup.ChainId      == locCustTable.CompanyChainId
                            &&  locsmmBusRelChainGroup.AVANetPG2    == locAVAPriceIncreasePriceDiscGroup.GroupId
                    {
                        locNoOfChains++;
                    }
                    break;

                default:
                    // default statement
                    break;
            }

            // Anzahl Preise der Preisgruppe
            /*
            select count(Recid)
            from    locPriceDiscTable
            where   locPriceDiscTable.relation         == PriceType::KCS_PRCActionPriceSales
                &&  locPriceDiscTable.AccountCode      == PriceDiscPartyCodeType::GroupId
                &&  locPriceDiscTable.AccountRelation  == locAVAPriceIncreasePriceDiscGroup.GroupId
                &&  locPriceDiscTable.ItemRelation      != ''
                &&  locPriceDiscTable.FromDate          <= locTodayBefore
                &&  (       locPriceDiscTable.ToDate    >= locTodayBefore
                        ||  locPriceDiscTable.ToDate    == dateNull()       );

            locAVANoOfPrices +=  int642int(locPriceDiscTable.RecId);
            */
            locAVANoOfPrices = this.countPriceGroupPricesFromPriceGroupId(  locAVAPriceIncreaseTable.PriceIncreaseSet,
                                                                            locAVAPriceIncreasePriceDiscGroup.GroupId, 
                                                                            PriceType::PriceSales          );
        }
        /*
        if (    locAVAPriceIncreasePriceDiscGroup.Module    == ModuleInventCustVend::Cust 
            &&  locAVAPriceIncreasePriceDiscGroup.Type      == PriceGroupType::PriceGroup)
        {
            /*
            // Ketten, die diese Preisgruppe referenziert haben
            while select locNDXMultipleS_smmBusRelChainGroup
            where locNDXMultipleS_smmBusRelChainGroup.PriceGroupId == locAVAPriceIncreasePriceDiscGroup.GroupId
            {
                locNoOfChains++;
                while select locsmmBusRelChainGroup
                where locsmmBusRelChainGroup.ChainId == locNDXMultipleS_smmBusRelChainGroup.RefChainId
                {
                    select count(RecId)
                    from    locCustTable 
                    where   locCustTable.CompanyChainId == locsmmBusRelChainGroup.ChainId;

                    locAVANoOfCustomers += locCustTable.RecId;
                }
            }
            */

            // Anzahl Preise der Preisgruppe
            /*
            select count(Recid) 
            from    locPriceDiscTable
            where   locPriceDiscTable.relation          == PriceType::PriceSales 
                &&  locPriceDiscTable.AccountCode       == PriceDiscPartyCodeType::GroupId
                &&  locPriceDiscTable.AccountRelation   == locAVAPriceIncreasePriceDiscGroup.GroupId
                &&  locPriceDiscTable.ItemRelation      != ''
                &&  locPriceDiscTable.FromDate          <= locTodayBefore
                &&  (       locPriceDiscTable.ToDate    >= locTodayBefore
                        ||  locPriceDiscTable.ToDate    == dateNull()       );

            locAVANoOfPrices +=  int642int(locPriceDiscTable.RecId);
            */
            locAVANoOfPrices = this.countPriceGroupPricesFromPriceGroupId(  locAVAPriceIncreasePriceDiscGroup.GroupId,
                                                                            PriceType::PriceSales                       );
        }
        */
        ttsbegin;
        locAVAPriceIncreasePriceDiscGroup.NoOfCustomers = locAVANoOfCustomers + locNoOfChains;
        locAVAPriceIncreasePriceDiscGroup.NoOfPrices    = locAVANoOfPrices;
        locAVAPriceIncreasePriceDiscGroup.write();
        ttscommit;
    }
    return retVal;
}

/// <summary>
///     AVA <c>countPriceGroupPricesFromPriceGroupId</c> method.
/// </summary>
/// <param name="_priceGroupId">
///     <c>PriceGroupId</c> as type
/// </param>
/// <param name="_pricsType">
///     <c>PriceType</c> as type
/// </param>
/// <returns>
///     <c>int</c> as return value
/// </returns>
public int countPriceGroupPricesFromPriceGroupId(   AVAPriceIncreaseSet _priceIncreaseSet,
                                                    PriceGroupId        _priceGroupId,
                                                    PriceType           _pricsType  = PriceType::PriceSales)
{
    int                     retVal;

    PriceDiscTable          locPriceDiscTable;
    InventTable             locInventTable;
    AVAPriceIncreaseLine    locAVAPriceIncreaseLine;
    date                    locToday;
    date                    locTodayBefore;

    Set                     locKCS_GoodsIdSetDefined;
    SetEnumerator           locKCS_GoodsIdSetEnumeratorDefined;

    locKCS_GoodsIdSetDefined    = new Set(Types::String);
    locKCS_GoodsIdSetDefined    = AVAPriceIncreaseTable::find(_priceIncreaseSet).getKCS_GoodsIdSetDefined();

    if (locKCS_GoodsIdSetDefined.empty())
    {
        return  retVal;
    }
    else
    {
        locKCS_GoodsIdSetEnumeratorDefined = locKCS_GoodsIdSetDefined.getEnumerator();
    }


    locToday        = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    locTodayBefore  = locToday - 1;

    locKCS_GoodsIdSetEnumeratorDefined.reset();
    while (locKCS_GoodsIdSetEnumeratorDefined.moveNext())
    {
        // Anzahl Preise der Preisgruppe
        select count(Recid)
        from    locPriceDiscTable
        where   locPriceDiscTable.relation          == _pricsType
            &&  locPriceDiscTable.AccountCode       == PriceDiscPartyCodeType::GroupId
            &&  locPriceDiscTable.AccountRelation   == _priceGroupId
            &&  locPriceDiscTable.ItemRelation      != ''
            &&  locPriceDiscTable.FromDate          <= locTodayBefore
            &&  (       locPriceDiscTable.ToDate    >= locTodayBefore
                    ||  locPriceDiscTable.ToDate    == dateNull()       )
            join locInventTable
            where locInventTable.ItemId             == locPriceDiscTable.ItemRelation
                join    locAVAPriceIncreaseLine
                where   locAVAPriceIncreaseLine.KCS_GoodsId         == locInventTable.KCS_GoodsId
                    &&  locAVAPriceIncreaseLine.PriceIncreaseSet    == _priceIncreaseSet
                    &&  locAVAPriceIncreaseLine.KCS_GoodsId         == locKCS_GoodsIdSetEnumeratorDefined.current();

        retVal += int642int(locPriceDiscTable.RecId);
    }

    return retVal;
}

/// <summary>
///     AVA <c>createPriceDiscAdmTableFromAVAPriceIncreaseTable</c> method.
/// </summary>
/// <param name="_avaPriceIncreaseTable">
///     <c>AVAPriceIncreaseTable</c> as type
/// </param>
/// <param name="_avaPriceIncreasePriceDiscGroup">
///     <c>AVAPriceIncreasePriceDiscGroup</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean createPriceDiscAdmTableFromAVAPriceIncreaseTable(    AVAPriceIncreaseTable           _avaPriceIncreaseTable          = this.priceIncreaseTable(), 
                                                                    AVAPriceIncreasePriceDiscGroup  _avaPriceIncreasePriceDiscGroup = null                      )
{
    boolean                         retVal;

    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;
    PriceDiscAdmTable               locPriceDiscAdmTable;
    PriceDiscAdmTrans               locPriceDiscAdmTrans;
    real                            locLineNum;
    PriceDiscAdmName                locPriceDiscAdmName;
    PriceDiscTable                  locPriceDiscTable;

    AVAPriceIncreaseTable           locAVAPriceIncreaseTable;
    InventTable                     locInventTable;
    AVAPriceIncreaseLine            locAVAPriceIncreaseLine;

    date                            locToday;
    date                            locTodayBefore;

    Set                             locKCS_GoodsIdSetDefined;
    SetEnumerator                   locKCS_GoodsIdSetEnumeratorDefined;
    Set                             locKCS_GoodsIdSetDefinedZero;
    SetEnumerator                   locKCS_GoodsIdSetEnumeratorDefinedZero;

    PriceDiscAdmSmartRound          locPriceDiscAdmSmartRound;

    AVAPriceInceaseComplete         locAVAPriceInceaseComplete;

    retVal                              = true;

    locToday                            = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    locTodayBefore                      = locToday - 1;

    locAVAPriceIncreaseTable            = _avaPriceIncreaseTable;
    locAVAPriceIncreasePriceDiscGroup   = _avaPriceIncreasePriceDiscGroup;

    locAVAPriceInceaseComplete          = locAVAPriceIncreasePriceDiscGroup.priceDiscGroup().AVAPriceInceaseComplete;

    locKCS_GoodsIdSetDefined            = new Set(Types::String);
    locKCS_GoodsIdSetDefined            = AVAPriceIncreaseTable::find(locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet).getKCS_GoodsIdSetDefined();
    locKCS_GoodsIdSetDefinedZero        = new Set(Types::String);
    locKCS_GoodsIdSetDefinedZero        = AVAPriceIncreaseTable::find(locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet).getKCS_GoodsIdSetDefined(true);

    if (    locKCS_GoodsIdSetDefined.empty()
        &&  locKCS_GoodsIdSetDefinedZero.empty())
    {
        return  retVal;
    }
    else
    {
        locKCS_GoodsIdSetEnumeratorDefined      = locKCS_GoodsIdSetDefined.getEnumerator();
        locKCS_GoodsIdSetEnumeratorDefinedZero  = locKCS_GoodsIdSetDefinedZero.getEnumerator();
    }

    select firstonly locPriceDiscAdmName
    where locPriceDiscAdmName.DefaultRelation == PriceType::PriceSales;

    if(locPriceDiscAdmName.RecId)
    {
        if(locAVAPriceIncreasePriceDiscGroup.RecId)
        {
            if(locAVAPriceIncreasePriceDiscGroup.Blocked)
            {
                retVal = false;
            }
            if(locAVAPriceIncreasePriceDiscGroup.JournalNum == '')
            {
                ttsbegin;
                locPriceDiscAdmTable.clear();
                locPriceDiscAdmTable.initFromPriceDiscAdmName(locPriceDiscAdmName);
                locPriceDiscAdmTable.Name = strFmt("@NDX:NXAPriceIncreaseP1P2", locAVAPriceIncreasePriceDiscGroup.GroupId + ' -', locAVAPriceIncreaseTable.FromDate);
                locPriceDiscAdmTable.insert();
                if(locPriceDiscAdmTable.RecId)
                {
                    locPriceDiscAdmTable.selectForUpdate(true);
                    locPriceDiscAdmTable.AVAPriceIncreaseSet = locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet;
                    locPriceDiscAdmTable.update();
                    locAVAPriceIncreasePriceDiscGroup.selectForUpdate(true);
                    locAVAPriceIncreasePriceDiscGroup.JournalNum = locPriceDiscAdmTable.JournalNum;
                    locAVAPriceIncreasePriceDiscGroup.update();

                    locKCS_GoodsIdSetEnumeratorDefined.reset();
                    while (locKCS_GoodsIdSetEnumeratorDefined.moveNext())
                    {
                        while select locPriceDiscTable
                        where   locPriceDiscTable.relation          == PriceType::PriceSales
                            &&  locPriceDiscTable.AccountCode       == PriceDiscPartyCodeType::GroupId
                            &&  locPriceDiscTable.AccountRelation   == locAVAPriceIncreasePriceDiscGroup.GroupId
                            &&  locPriceDiscTable.ItemCode          == PriceDiscProductCodeType::Table
                            &&  locPriceDiscTable.ItemRelation      != ''
                            &&  locPriceDiscTable.FromDate          <= locTodayBefore
                            &&  (       locPriceDiscTable.ToDate    >= locTodayBefore 
                                    ||  locPriceDiscTable.ToDate    == dateNull()       )
                            join locInventTable
                            where locInventTable.ItemId             == locPriceDiscTable.ItemRelation
                                join    locAVAPriceIncreaseLine
                                where   locAVAPriceIncreaseLine.KCS_GoodsId         == locInventTable.KCS_GoodsId
                                    &&  locAVAPriceIncreaseLine.PriceIncreaseSet    == locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet
                                    &&  locAVAPriceIncreaseLine.KCS_GoodsId         == locKCS_GoodsIdSetEnumeratorDefined.current()
                        {
                            locLineNum++;

                            locPriceDiscAdmTrans.clear();
                            locPriceDiscAdmTrans.initFromPriceDiscTable(locPriceDiscTable);
                            locPriceDiscAdmTrans.JournalNum         = locPriceDiscAdmTable.JournalNum;
                            locPriceDiscAdmTrans.LineNum            = locLineNum;

                            if(locAVAPriceIncreaseLine.PriceIncreasePercentage)
                            {
                                locPriceDiscAdmTrans.KCS_AmountOld  = locPriceDiscAdmTrans.Amount;
                                locPriceDiscAdmTrans.Amount         = locPriceDiscAdmTrans.KCS_AmountOld + locPriceDiscAdmTrans.KCS_AmountOld * locAVAPriceIncreaseLine.PriceIncreasePercentage / 100;
                            }
                            else
                            {
                                locPriceDiscAdmTrans.KCS_AmountOld  = locPriceDiscAdmTrans.Amount;
                                locPriceDiscAdmTrans.Amount         = locPriceDiscAdmTrans.KCS_AmountOld;
                            }
                            locPriceDiscAdmTrans.KCS_NewAndClose    = NoYes::Yes;
                            locPriceDiscAdmTrans.PriceDiscTableRef  = locPriceDiscTable.RecId;
                            locPriceDiscAdmTrans.FromDate           = locAVAPriceIncreaseTable.FromDate;
                            locPriceDiscAdmTrans.insert();
                        }
                    }

                    if(locAVAPriceInceaseComplete == NoYes::Yes)
                    {
                        locKCS_GoodsIdSetEnumeratorDefinedZero.reset();
                        while (locKCS_GoodsIdSetEnumeratorDefinedZero.moveNext())
                        {
                            while select locPriceDiscTable
                            where   locPriceDiscTable.relation          == PriceType::PriceSales
                                &&  locPriceDiscTable.AccountCode       == PriceDiscPartyCodeType::GroupId
                                &&  locPriceDiscTable.AccountRelation   == locAVAPriceIncreasePriceDiscGroup.GroupId
                                &&  locPriceDiscTable.ItemCode          == PriceDiscProductCodeType::Table
                                &&  locPriceDiscTable.ItemRelation      != ''
                                &&  locPriceDiscTable.FromDate          <= locTodayBefore
                                &&  (       locPriceDiscTable.ToDate    >= locTodayBefore
                                        ||  locPriceDiscTable.ToDate    == dateNull()       )
                                join locInventTable
                                where locInventTable.ItemId             == locPriceDiscTable.ItemRelation
                                    join    locAVAPriceIncreaseLine
                                    where   locAVAPriceIncreaseLine.KCS_GoodsId         == locInventTable.KCS_GoodsId
                                        &&  locAVAPriceIncreaseLine.PriceIncreaseSet    == locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet
                                        &&  locAVAPriceIncreaseLine.KCS_GoodsId         == locKCS_GoodsIdSetEnumeratorDefinedZero.current()
                            {
                                locLineNum++;

                                locPriceDiscAdmTrans.clear();
                                locPriceDiscAdmTrans.initFromPriceDiscTable(locPriceDiscTable);
                                locPriceDiscAdmTrans.JournalNum         = locPriceDiscAdmTable.JournalNum;
                                locPriceDiscAdmTrans.LineNum            = locLineNum;

                                if(locAVAPriceIncreaseLine.PriceIncreasePercentage)
                                {
                                    locPriceDiscAdmTrans.KCS_AmountOld  = locPriceDiscAdmTrans.Amount;
                                    locPriceDiscAdmTrans.Amount         = locPriceDiscAdmTrans.KCS_AmountOld + locPriceDiscAdmTrans.KCS_AmountOld * locAVAPriceIncreaseLine.PriceIncreasePercentage / 100;
                                }
                                else
                                {
                                    locPriceDiscAdmTrans.KCS_AmountOld  = locPriceDiscAdmTrans.Amount;
                                    locPriceDiscAdmTrans.Amount         = locPriceDiscAdmTrans.KCS_AmountOld;
                                }
                                locPriceDiscAdmTrans.KCS_NewAndClose    = NoYes::Yes;
                                locPriceDiscAdmTrans.PriceDiscTableRef  = locPriceDiscTable.RecId;
                                locPriceDiscAdmTrans.FromDate           = locAVAPriceIncreaseTable.FromDate;
                                locPriceDiscAdmTrans.insert();
                            }
                        }
                    }
                    // smoothing deactivated req 12033
                    /*
                    if(locPriceDiscAdmTrans.RecId) // at least one position created
                    {
                        locPriceDiscAdmSmartRound = PriceDiscAdmSmartRound::construct();
                        locPriceDiscAdmSmartRound.setJournalNum(locPriceDiscAdmTable.JournalNum);
                        locPriceDiscAdmSmartRound.runOperation();
                    }
                    */
                }
                ttscommit;
            }
        }
    }
    return retVal;
}

/// <summary>
///     AVA <c>priceIncreaseTable</c> method.
/// </summary>
/// <param name="_forUpdate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>AVAPriceIncreaseTable</c> as return value
/// </returns>
public AVAPriceIncreaseTable priceIncreaseTable(boolean _forUpdate = false)
{
    AVAPriceIncreaseTable retVal;

    retVal = AVAPriceIncreaseTable::find(this.PriceIncreaseSet);

    return retVal;
}

/// <summary>
///     AVA <c>priceDiscGroup</c> method.
/// </summary>
/// <param name="_forUpdate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>PriceDiscGroup</c> as return value
/// </returns>
public PriceDiscGroup priceDiscGroup(boolean _forUpdate = false)
{
    PriceDiscGroup retVal;

    retVal = PriceDiscGroup::find(  this.Module,
                                    this.Type, 
                                    this.GroupId    );

    return retVal;
}

/// <summary>
/// desigmed from AVA
/// </summary>
/// <returns></returns>
public boolean  isJourPosted()
{
    PriceDiscAdmTable           priceDiscAdmTable = PriceDiscAdmTable::find(this.JournalNum);

    return  priceDiscAdmTable.Posted;
}
